using Astrea.BattleActions;
using UnityEngine;
using UnityEngine.Localization.SmartFormat;

namespace Astrea;

[CreateAssetMenu(fileName = "PlatinumStarOmenData", menuName = "Data/Battle/Omens System/Omen Data/Orion/PlatinumStar Omen Data")]
public class PlatinumStarOmenData : OmenData
{
	[Header("Debt Enhancer Omen")]
	[SerializeField]
	private PurifyEffectBasedAction orionPlatinumStarAction;

	[SerializeField]
	private AreaPurifyEffectBasedAction orionAreaPlatinumStarAction;

	[SerializeField]
	private int increaseDevotionOrbAmount;

	[SerializeField]
	private int lightShieldAmount = 1;

	[SerializeField]
	private Effect vowReinforcementEffect;

	public PurifyEffectBasedAction OrionPlatinumStarAction => orionPlatinumStarAction;

	public AreaPurifyEffectBasedAction OrionAreaPlatinumStarAction => orionAreaPlatinumStarAction;

	public override void Initialize(OmenInstance omenInstance)
	{
		ReferenceSingleton<OrionOmensHandler>.Instance.PlatinumStarOmenAction = delegate
		{
			omenInstance.ActivateOmenFeedback();
			return lightShieldAmount;
		};
		ReferenceSingleton<OrionOmensHandler>.Instance.PlatinumStarDevotionOmenAction = delegate(int value)
		{
			omenInstance.ActivateOmenFeedback();
			return value + increaseDevotionOrbAmount;
		};
	}

	public override void OmenRemoved()
	{
		ReferenceSingleton<OrionOmensHandler>.Instance.PlatinumStarOmenAction = null;
		ReferenceSingleton<OrionOmensHandler>.Instance.PlatinumStarDevotionOmenAction = null;
	}

	public override string OmenConvertedDescription()
	{
		return Smart.Format(base.OmenConvertedDescription(), Smart.Format(vowReinforcementEffect.GetLocalizedDescriptionExternal(), increaseDevotionOrbAmount), lightShieldAmount);
	}
}
